<script lang="ts">
import {api,type Copy} from '../../lib/api';
export let copy:Copy;let confirming=false;let busy=false;let error='';let key='';let payload='';let archived=false;
async function archive(){busy=true;error='';const next=JSON.stringify([copy.id,copy.revision]);if(payload!==next){payload=next;key=crypto.randomUUID();}try{await api(`/api/copies/${copy.id}/archive`,{revision:copy.revision,request_key:key});archived=true;confirming=false;window.dispatchEvent(new Event('library-inventory-changed'));}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<div class="archive_wrap">{#if error}<p role="alert" class="library-error">{error}</p>{/if}{#if archived}<p role="status">Copy archived. Its loan history is preserved.</p>{:else if confirming}<div class="archive_confirmation"><p>Archive {copy.label||`copy ${copy.id}`}? It will leave your current inventory; its loan history stays.</p><div class="library-actions"><button class="library-button secondary" disabled={busy} onclick={archive}>Confirm archive</button><button class="library-button secondary" disabled={busy} onclick={()=>confirming=false}>Cancel</button></div></div>{:else}<button class="library-button secondary" disabled={copy.out} onclick={()=>confirming=true}>Archive copy</button>{#if copy.out}<p class="library-help">Return this copy before archiving it.</p>{/if}{/if}</div>
<style>@layer components{.archive_wrap{display:grid;gap:var(--space-2)}.archive_confirmation{display:grid;gap:var(--space-2);padding:var(--space-3);border:var(--border-width) solid var(--border);border-radius:var(--radius-main);background:var(--background-3)}} </style>
